CREATE TABLE IF NOT EXISTS task_statuses (
  id SERIAL PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  display_order INTEGER NOT NULL DEFAULT 0,
  is_completed_status BOOLEAN NOT NULL DEFAULT false,
  created_at TIMESTAMP NOT NULL DEFAULT now()
);
INSERT INTO task_statuses (name, display_order, is_completed_status) VALUES
  ('Not Started', 1, false),
  ('In Progress', 2, false),
  ('Waiting on Client', 3, false),
  ('Completed', 4, true)
ON CONFLICT (name) DO NOTHING;
UPDATE activities SET status = 'Not Started' WHERE type = 'task' AND status = 'to_do';
UPDATE activities SET status = 'In Progress' WHERE type = 'task' AND status = 'in_progress';
UPDATE activities SET status = 'Waiting on Client' WHERE type = 'task' AND status = 'waiting';
UPDATE activities SET status = 'Completed' WHERE type = 'task' AND status = 'completed';

